sys_ux_client_script.script:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
* @param {ApiHelpers} params.helpers
*/
function handler({api, event, helpers, imports}) {

/**
 * Redirects to a specific URL within the ServiceNow Workspace.
 * @param {Object} params - Parameters passed to the function.
 * @param {Object} params.api - API object for navigation and actions.
 * @param {Object} params.event - Event data (if applicable).
 */
    console.log("Clicked navigation")
    const targetURL = '/$guided_setup.do#/content/2b09b6b0c3579a100ced12f1b40131bf?focus=ca764f12833d92109a4b66d0deaad304&group_focuses=&home_options=intro&scroll_to=&filter=all';
    // Use the navigateTo method to perform the redirection
    api.navigateTo({
        target: targetURL, // Target route within the workspace
        openInNewTab: true // Opens in a new tab within the workspace
    });

}
